INSERT INTO [dbo].[DATA_ZPJZK] ([ID], [DWDM], [WBNR], [HTML], [FBZ], [CJSJ], [FBBZ], [FBSJ], [FBZSFDM], [JZFJ], [CJZ], [CJZSFDM]) VALUES (N'4', N'58', N'&nbsp; &nbsp;&nbsp;特斯拉（Tesla）是一家电动汽车及清洁能源行业跨国公司，总部位于美国得克萨斯州&nbsp;，产销电动汽车、太阳能板、及储能设备与系统解决方案&nbsp;。现任CEO为埃隆·马斯克。&nbsp;&nbsp; &nbsp;&nbsp;2003年7月1日&nbsp;，马丁·艾伯哈德和马克·塔彭宁联合创立“特斯拉汽车公司”。2004年，马斯克投资后任公司董事长。创立之初，因成本失控，公司一度陷入危机。2008年，艾伯哈德和塔彭宁先后离开公司，马斯克出任CEO，着力进行改革、对外融资&nbsp;，同年，首款车型跑车Roadster问世&nbsp;。2010年，特斯拉获得美国政府4.65亿美元低息贷款，并在纳斯达克上市后，开始稳定发展&nbsp;。&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;2012年，第二款车型轿车Model S发布后，在世界范围刮起纯电动车热潮，公司首次扭亏为盈&nbsp;[3]&nbsp;[182]。2014年，特斯拉宣布共享专利技术。此后，于2015年发布第三款车型SUV&nbsp;Model X&nbsp;[4-5]&nbsp;[152]&nbsp;[180]，于2017年推出电动车Model 3、电动卡车Tesla Semi，于2019年推出电动皮卡Cybertruck，以及SUV&nbsp;Model Y等产品，除电动车外，还推出了Powerwall、Powerpack、Megapack等电池产品&nbsp;[180]，并逐步在中国、德国、韩国等地开办工厂。&nbsp;&nbsp; &nbsp;&nbsp;2021年，市值达到1.3万亿美元峰值后逐渐下降&nbsp;，截至2024年6月，特斯拉已累计生产超过600万辆电动车。&nbsp;2025年1月3日消息，特斯拉2024年中国市场的累计销量增长8.8%。&nbsp;[421]截至2025年3月10日收盘，特斯拉股价暴跌超15%。&nbsp;', N'<p><span style="font-size: 14px;">&nbsp; &nbsp;&nbsp;</span><font size="4">特斯拉（Tesla）是一家<a href="https://baike.baidu.com/item/%E7%94%B5%E5%8A%A8%E6%B1%BD%E8%BD%A6/429130?fromModule=lemma_inlink" target="_blank" style="">电动汽车</a>及<a href="https://baike.baidu.com/item/%E6%B8%85%E6%B4%81%E8%83%BD%E6%BA%90/22708?fromModule=lemma_inlink" target="_blank" style="">清洁能源</a>行业<a href="https://baike.baidu.com/item/%E8%B7%A8%E5%9B%BD%E5%85%AC%E5%8F%B8/247502?fromModule=lemma_inlink" target="_blank" style="">跨国公司</a>，总部位于美国<a href="https://baike.baidu.com/item/%E5%BE%97%E5%85%8B%E8%90%A8%E6%96%AF%E5%B7%9E/3439412?fromModule=lemma_inlink" target="_blank" style="">得克萨斯州</a><sup style="">&nbsp;</sup>，产销<a href="https://baike.baidu.com/item/%E7%94%B5%E5%8A%A8%E6%B1%BD%E8%BD%A6/429130?fromModule=lemma_inlink" target="_blank" style="">电动汽车</a>、<a href="https://baike.baidu.com/item/%E5%A4%AA%E9%98%B3%E8%83%BD%E6%9D%BF/6866848?fromModule=lemma_inlink" target="_blank" style="">太阳能板</a>、及储能设备与系统解决方案<sup style="">&nbsp;</sup>。现任CEO为<a href="https://baike.baidu.com/item/%E5%9F%83%E9%9A%86%C2%B7%E9%A9%AC%E6%96%AF%E5%85%8B/3776526?fromModule=lemma_inlink" target="_blank" style="">埃隆·马斯克</a>。<sup style="">&nbsp;</sup></font></p><p><span style="font-size: 14px;">&nbsp; &nbsp;&nbsp;</span><font size="4">2003年7月1日<sup style="">&nbsp;</sup>，<a href="https://baike.baidu.com/item/%E9%A9%AC%E4%B8%81%C2%B7%E8%89%BE%E4%BC%AF%E5%93%88%E5%BE%B7/12631089?fromModule=lemma_inlink" target="_blank" style="">马丁·艾伯哈德</a>和<a href="https://baike.baidu.com/item/%E9%A9%AC%E5%85%8B%C2%B7%E5%A1%94%E5%BD%AD%E5%AE%81/22205934?fromModule=lemma_inlink" target="_blank" style="">马克·塔彭宁</a>联合创立“特斯拉汽车公司”。2004年，马斯克投资后任公司董事长。创立之初，因成本失控，公司一度陷入危机。2008年，艾伯哈德和塔彭宁先后离开公司，马斯克出任CEO，着力进行改革、对外融资<sup style="">&nbsp;</sup>，同年，首款车型跑车<a href="https://baike.baidu.com/item/Roadster/22210414?fromModule=lemma_inlink" target="_blank" style="">Roadster</a>问世<sup style="">&nbsp;</sup>。2010年，特斯拉获得美国政府4.65亿美元低息贷款，并在<a href="https://baike.baidu.com/item/%E7%BA%B3%E6%96%AF%E8%BE%BE%E5%85%8B/17437?fromModule=lemma_inlink" target="_blank" style="">纳斯达克</a>上市后，开始稳定发展<sup style="">&nbsp;</sup>。</font></p><p><span style="font-size: 14px;">&nbsp; &nbsp;&nbsp;</span><span style="font-size: 14px;">&nbsp; &nbsp;&nbsp;</span><span style="font-size: large;">2012年，第二款车型轿车</span><a href="https://baike.baidu.com/item/Model%20S/19494409?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Model S</a><span style="font-size: large;">发布后，在世界范围刮起纯电动车热潮，公司首</span><span style="font-size: large;">次扭亏为盈</span><sup>&nbsp;[3]<em></em></sup><sup>&nbsp;[182]<em></em></sup><span style="font-size: large;">。2014年，特斯拉宣布共享专利技术</span><span style="font-size: large;">。此后，于2015年发布第三款车型SUV&nbsp;</span><a href="https://baike.baidu.com/item/Model%20%20X/18585210?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Model X</a><sup>&nbsp;[4-5]<em></em><em></em></sup><sup>&nbsp;[152]<em></em></sup><sup>&nbsp;[180]<em></em></sup><span style="font-size: large;">，于2017年推出电动车</span><a href="https://baike.baidu.com/item/Model%203/16825147?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Model 3</a><span style="font-size: large;">、电动卡车</span><a href="https://baike.baidu.com/item/Tesla%20Semi/22210251?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Tesla Semi</a><span style="font-size: large;">，于2019年推出电动皮卡</span><a href="https://baike.baidu.com/item/Cybertruck/24158423?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Cybertruck</a><span style="font-size: large;">，以及SUV&nbsp;</span><a href="https://baike.baidu.com/item/Model%20Y/56033277?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Model Y</a><span style="font-size: large;">等产品，除电动车外，还推出了</span><a href="https://baike.baidu.com/item/Powerwall/17517959?fromModule=lemma_inlink" target="_blank" style="font-size: large;">Powerwall</a><span style="font-size: large;">、Powerpack、Megapack等电池产品</span><sup>&nbsp;[180]<em></em></sup><span style="font-size: large;">，并逐步在中国、德国、韩国等地开办工厂</span><span style="font-size: large;">。</span><sup>&nbsp;</sup></p><p><span style="font-size: 14px;">&nbsp; &nbsp;&nbsp;</span><font size="4">2021年，市值达到1.3万亿美元峰值后逐渐下降<sup style="">&nbsp;</sup>，截至2024年6月，特斯拉已累计生产超过600万辆电动车。<sup style="">&nbsp;</sup>2025年1月3日消息，特斯拉2024年中国市场的累计销量增长8.8%。<sup style="">&nbsp;[421]<em></em></sup>截至2025年3月10日收盘，特斯拉股价暴跌超15%。<sup style="">&nbsp;</sup></font></p><img src="/img/upload/ZPJZK/1745245456539_.jpg" contenteditable="false" width="50%"/><p><br/></p>', N'msk', N'2025-04-21 22:30:25.753', N'1', N'2025-04-21 22:48:54.547', N'3', NULL, N'msk', N'3')
GO

INSERT INTO [dbo].[DATA_ZPJZK] ([ID], [DWDM], [WBNR], [HTML], [FBZ], [CJSJ], [FBBZ], [FBSJ], [FBZSFDM], [JZFJ], [CJZ], [CJZSFDM]) VALUES (N'8', N'58', N'特斯拉大升级！', N'<p><font face="仿宋" size="7"><b>特斯拉大升级！</b></font></p><p><video src="/img/upload/Wangeditor/1745249786901_.mp4" controls="controls"></video></p>', N'msk', N'2025-04-21 22:52:47.377', N'1', N'2025-04-21 23:53:55.667', N'3', NULL, N'msk', N'3')
