INSERT INTO [dbo].[XMCGK] ([ID], [XMMC], [XMNR], [STUID], [QYDM], [CJSJ], [XMLX], [XMFJ]) VALUES (N'1', N'门诊信息系统', N'本项目旨在开发一套高效、安全、便捷的门诊信息管理系统，实现患者挂号、医生排班、电子病历、处方管理、费用结算等功能。系统支持多终端访问，提高医院门诊管理效率，减少患者等待时间，并保障医疗数据安全。采用B/S架构，结合数据库存储、数据加密及权限控制，确保信息流转的准确性和隐私性，为医院和患者提供智能化服务。', N'1211', N'1', N'2025-03-15 17:14:29.600', N'科研', N'/img/upload/XMCGK/1742047540091_罗老湿-成绩单.csv')
GO

INSERT INTO [dbo].[XMCGK] ([ID], [XMMC], [XMNR], [STUID], [QYDM], [CJSJ], [XMLX], [XMFJ]) VALUES (N'2', N'乡愁的研究', N'乡愁

小时候，乡愁是一枚小小的邮票，
我在这头，母亲在那头。

长大后，乡愁是一张窄窄的船票，
我在这头，新娘在那头。

后来啊，乡愁是一方矮矮的坟墓，
我在外头，母亲在里头。

而现在，乡愁是一湾浅浅的海峡，
我在这头，大陆在那头。', N'1211', N'1', N'2025-03-15 22:25:10.387', N'竞赛', NULL)
GO

INSERT INTO [dbo].[XMCGK] ([ID], [XMMC], [XMNR], [STUID], [QYDM], [CJSJ], [XMLX], [XMFJ]) VALUES (N'3', N'基于Springboot的学生管理系统', N'基于Spring Boot的学生管理系统项目内容（约1000字）
一、项目概述
本系统旨在实现学生信息的数字化管理，提供学生档案、课程成绩、考勤记录等功能的全生命周期管理。基于Spring Boot框架快速开发，采用B/S架构，支持多角色（管理员、教师、学生）权限控制，具备响应式前端界面，适合高校或培训机构使用。

二、核心功能模块
学生信息管理
支持CRUD操作（增删改查）
字段包含：学号、姓名、性别、出生日期、专业、班级、联系方式
支持Excel批量导入/导出
课程管理
课程基本信息维护（课程号、名称、学分、教师、开课学期）
课程表动态生成与冲突检测
支持选课功能（学生端）
成绩管理
成绩录入（支持单条/批量导入）
成绩统计分析（平均分、最高/低分、分布曲线）
成绩预警机制（不及格科目自动提醒）
考勤管理
课堂签到记录（支持二维码/NFC签到）
考勤统计报表生成
缺勤预警规则配置
系统安全
基于Spring Security的RBAC权限模型
双因素认证（密码+动态验证码）
操作日志审计追踪
三、技术选型
层级	技术栈	说明
后端框架	Spring Boot 2.7.x	快速构建RESTful API
安全框架	Spring Security + JWT	令牌认证与权限控制
持久层	MyBatis-Plus + MySQL 8.0	ORM框架+关系型数据库
前端框架	Vue3 + Element Plus	渐进式前端框架+UI组件库
缓存	Redis	热点数据缓存
API文档	Swagger3	接口文档自动生成
部署	Docker + Nginx	容器化部署与反向代理

四、数据库设计（关键表结构）
sql
-- 学生表
CREATE TABLE student (
    id VARCHAR(32) PRIMARY KEY COMMENT ''主键ID'',
    student_id VARCHAR(20) UNIQUE COMMENT ''学号'',
    name VARCHAR(50) NOT NULL COMMENT ''姓名'',
    gender TINYINT COMMENT ''性别'',
    birthdate DATE COMMENT ''出生日期'',
    major VARCHAR(50) COMMENT ''专业'',
    class_name VARCHAR(50) COMMENT ''班级'',
    phone VARCHAR(20) COMMENT ''联系电话'',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT ''创建时间''
);
 
-- 课程表
CREATE TABLE course (
    id VARCHAR(32) PRIMARY KEY,
    course_code VARCHAR(20) UNIQUE COMMENT ''课程编号'',
    course_name VARCHAR(100) NOT NULL COMMENT ''课程名称'',
    credit FLOAT COMMENT ''学分'',
    teacher VARCHAR(50) COMMENT ''授课教师'',
    semester VARCHAR(20) COMMENT ''开课学期''
);
 
-- 成绩表
CREATE TABLE score (
    id VARCHAR(32) PRIMARY KEY,
    student_id VARCHAR(20) COMMENT ''学号'',
    course_code VARCHAR(20) COMMENT ''课程编号'',
    score DECIMAL(5,2) COMMENT ''成绩'',
    exam_date DATE COMMENT ''考试日期'',
    FOREIGN KEY (student_id) REFERENCES student(student_id),
    FOREIGN KEY (course_code) REFERENCES course(course_code)
);
 
-- 用户表（Spring Security专用）
CREATE TABLE sys_user (
    username VARCHAR(50) PRIMARY KEY,
    password VARCHAR(100) NOT NULL,
    role VARCHAR(50) NOT NULL COMMENT ''角色标识''
);
五、核心代码示例
REST控制器层（学生信息）
java
@RestController
@RequestMapping("/api/students")
public class StudentController {
    @Autowired
    private StudentService studentService;
 
    @GetMapping
    public Result<PageInfo<Student>> list(
            @RequestParam(defaultValue = "1") int pageNum,
            @RequestParam(defaultValue = "10") int pageSize,
            StudentQuery query) {
        return Result.success(studentService.page(pageNum, pageSize, query));
    }
 
    @PostMapping
    public Result<Void> add(@Valid @RequestBody Student student) {
        studentService.save(student);
        return Result.success();
    }
}
Service层（事务管理）
java
@Service
public class StudentServiceImpl implements StudentService {
    @Autowired
    private StudentMapper studentMapper;
 
    @Transactional(rollbackFor = Exception.class)
    @Override
    public void batchImport(List<Student> students) {
        studentMapper.batchInsert(students);
    }
}
安全配置（Spring Security）
java
@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {
    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
            .antMatchers("/api/public/**").permitAll()
            .antMatchers("/api/admin/**").hasRole("ADMIN")
            .anyRequest().authenticated()
            .and()
            .formLogin()
            .loginPage("/login")
            .permitAll()
            .and()
            .logout()
            .permitAll();
    }
}
