-- ----------------------------
-- Procedure structure for usp_GetStuGzjlData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetStuGzjlData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetStuGzjlData]
GO

CREATE PROCEDURE [dbo].[usp_GetStuGzjlData]  
	  @YHM NVARCHAR(50)
AS  
BEGIN  
    /*  
        作用：  通过学生用户名获取学生 工作经历数据
        时间：2025年3月10日  
    */  

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  

	select a.*,
	b.XSXM,
	b.XSXB,
	b.SSBJ,
	b.ZYDM,
	b.SFZH,
	b.ZZMM,
	b.SSNJ,
	b.JYZT,
	b.XSZP,
	b.FZJS
	--exec LuodengTable 'DATA_STUDENT'
	from GZJLK a
	left join DATA_STUDENT b on a.STUID=b.ID
	where b.YHM=@YHM

	--- 获取工作经历事项
	select a.* from GZJLSXK a
	left join GZJLK b on a.GZJLDM=b.ID
	left join DATA_STUDENT c on b.STUID=c.ID
	where c.YHM=@YHM

END
GO


-- ----------------------------
-- Procedure structure for usp_GetZphData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetZphData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetZphData]
GO

CREATE PROCEDURE [dbo].[usp_GetZphData]
		@QYDM int ,-- 启用代码 1.0 。2全部


		@ISJUSTONE int ,--是否只获取一条招聘会数据，@ISJUSTONE为1时，其他参数（除了@ZPHID）无用
		@ZPHID int ,-- 招聘会ID，当@ISJUSTONE为1时有用


		@ISJUSTONEYH int, --是否只获取一个用户发布的， 
		@YHM nvarchar(50) ,-- 当@ISJUSTYH为1时，会用到此参数！
		@YHSFDM int,

		@getBySHR int , --是否通过审核人获取招聘会
		@SHR nvarchar(50)  ,--审核人用户名
		@SHRSFDM int  --审核人用户SFDM

		-- exec usp_GetZphData 2,0,-1,1,'lls',2,0,'-1',-1
		as
BEGIN  
    /*  
        作用：获取招聘会数据
        时间：2025年2月14日  
		实例：exec usp_GetZphData 1,0,-1,0,'-1',-1,0,'-1',-1 
		exec usp_GetZphData 2,0,-1,1,'lls',2,0,'-1',-1
    */  
	--select FZJS from DATA_STUDENT

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	--exec LuodengTable 'DATA_ZPHJLK'
	if @QYDM=2
		begin 
			
			if @ISJUSTONE=1  --只获取一条
				begin
				
					select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 2 then b.JSMC
							when 3 then c.YHXM
						end as FBZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPHJLK a
							left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
							left join DWYHK c on a.FBZ=b.DLZH and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where a.ID=@ZPHID
				end

		   else	if @ISJUSTONEYH=1  -- 只获取一个用户的
				begin
				select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 2 then b.JSMC
						when 3 then c.YHXM
					end as FBZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPHJLK a
						left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
						left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.FBZ=@YHM and a.FBZSFDM=@YHSFDM 
						--exec LuodengTable 'DATA_ZPHJLK'
				end
		   else if @getBySHR=1
				begin
					select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 2 then b.JSMC
						when 3 then c.YHXM
					end as FBZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPHJLK a
						left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
						left join DWYHK c on a.FBZ=b.DLZH and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.SHRYHM=@SHR and a.SHRSFDM=@SHRSFDM
				end

		 else	if @ISJUSTONE=0 and   @getBySHR=0 and @ISJUSTONEYH=0 
				select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 2 then b.JSMC
							when 3 then c.YHXM
						end as FBZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPHJLK a
							left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
							left join DWYHK c on a.FBZ=b.DLZH and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM
				return 

		end 

		
		else
			begin 
				if @ISJUSTONE=1  --只获取一条
					select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 2 then b.JSMC
							when 3 then c.YHXM
						end as FBZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPHJLK a
							left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where a.ID=@ZPHID  and a.QYDM=@QYDM

			   else	if @ISJUSTONEYH=1  -- 只获取一个用户的
					select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 2 then b.JSMC
							when 3 then c.YHXM
						end as FBZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPHJLK a
							left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.FBZ=@YHM and a.FBZSFDM=@YHSFDM   and a.QYDM=@QYDM
						--	exec LuodengTable 'DATA_ZPHJLK'
				
			 else	if @getBySHR=1
				begin 
						select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 2 then b.JSMC
							when 3 then c.YHXM
						end as FBZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPHJLK a
							left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.SHRYHM=@SHR and a.SHRSFDM=@SHRSFDM and a.QYDM=@QYDM
							end
				else	if @ISJUSTONE=0 and   @getBySHR=0 and @ISJUSTONEYH=0
					select a.*,
							case a.FBZSFDM
								when 1 then d.MC--管理员
								when 2 then b.JSMC
								when 3 then c.YHXM
							end as FBZMC,
							f.DWMC,
							f.GSMC
							from DATA_ZPHJLK a
								left join JSDMK b on a.FBZ=b.DLZH and a.FBZSFDM=2
								left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
								left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
								left join DATA_DWDMK f on a.DWDM=f.DWDM where   a.QYDM=@QYDM
					return 
			end 


 
		
END
GO


