-- Procedure structure for usp_AllUserGetGongGaoData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_AllUserGetGongGaoData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_AllUserGetGongGaoData]
GO

CREATE PROCEDURE [dbo].[usp_AllUserGetGongGaoData]  
	 @YHSFDM int,-- 用户身份代码
	 @YHM NVARCHAR(50),-- 用户名
	 @QYDM int ,--1 只获取启用的，0 只获取不启用的 ，-1获取全部 
	 @JUSTONE int, -- 1 只获取一条，0 获取多一条
	 @GGID int  -- 公告ID，当@JUSTONE为1时才会用到
AS  
BEGIN  
    /*  
        作用：获取招聘公告信息： DWZPGGK，
        时间：2025年3月11日  
		管理员也可以发布招聘公告
		教师也可以发布公告
    */  
	--select * from DWZPGGK
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	--select * from YHSFDMK
	if @JUSTONE=1
			select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.ID=@GGID
	else
		begin
			if @YHSFDM=1 or @YHSFDM =2  or @YHSFDM =4--管理员 --教师 -- 学生
		begin 
			if @QYDM=1 
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.QYDM=1
			if @QYDM=0
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.QYDM=0
			if @QYDM=-1
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
	end
			if @YHSFDM=3  --单位
		begin 
			if @QYDM=1 
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.QYDM=1 and a.FBZ=@YHM
			if @QYDM=0
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.QYDM=0 and a.FBZ=@YHM
			if @QYDM=-1
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from DWZPGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH where a.FBZ=@YHM
	end
		end
END
GO


