-- Procedure structure for usp_GetJobData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetJobData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetJobData]
GO

CREATE PROCEDURE [dbo].[usp_GetJobData]  
	@IsJustOne int,-- 是否只是获取一条
	@gwdm  int,-- 当@IsJustOne为1时，此参数才有用
	@QYDM    int,-- 1时只获取启用的，0 只获取未启用的，2 获取全部
	@IsByFBZ  int,-- 是否通过发布者获取
	@FBZ nvarchar(50), -- 发布者  ，@IsByFBZ为1时有效
	@SXBZ int  --实习标志，1只获取实习，0 只获取正式岗位，2全部
AS  
BEGIN  
    /*  
        作用：获取岗位数据
        时间：2025年2月14日  
		@IsJustOne和 @IsByFBZ 不可能同时为1
			select * from DATA_GWDMK where FBZ='ozf'
	exec usp_GetJobData 0,-1,1,1,'ozf',2
    */  
	 
 
    -- 防止额外结果集干扰SELECT语句
	--  select * from DATA_GWDMK
    SET NOCOUNT ON; 
	if @IsJustOne=1  --会获取一个,不做任何判断
		select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,f.FLMC,b.GSJJHTML,b.GSJJHTML,b.GSJJHTML,
			CASE 
				WHEN a.FBZYHSFDM=1 THEN d.MC
				WHEN a.FBZYHSFDM=3 THEN c.YHXM
				ELSE '暂未查询到发布者'
			END  as FBZXM
			from DATA_GWDMK a 
			left join DATA_DWDMK b on a.DWDM=b.DWDM
			left join DWYHK c on a.FBZ=c.YHM
			left join GLYDMK d on a.FBZ=d.DLZH
			left join SFDMK e on a.GZSF=e.SFDM
			left join GWFLK f on a.GWFL=f.ID
			where a.ID=@gwdm 
	else
		begin 
			if @IsByFBZ=1 --通过发布者获取
				begin 
					if @QYDM=2 --获取全部的，不考虑是否启用
						begin 
						  if @SXBZ=2 --获取全部的，不考虑是否为实习
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
									where a.FBZ=@FBZ
							else
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
									where a.FBZ=@FBZ and a.SXBZ=@SXBZ
						end	
					else
						begin
							if @SXBZ=2
								begin 
									 
									select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
									where a.FBZ=@FBZ and a.QYDM=@QYDM
								end
							else
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
									where a.FBZ=@FBZ and a.QYDM=@QYDM and a.SXBZ=@SXBZ
						end
				end
			else
				begin   --不做发布者限制
					if @QYDM=2 --获取全部的，不考虑是否启用
						begin 
						  if @SXBZ=2 --获取全部的，不考虑是否为实习
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
							else
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join SFDMK e on a.GZSF=e.SFDM
									left join GWFLK f on a.GWFL=f.ID
									where  a.SXBZ=@SXBZ
						end	
					else
						begin
							if @SXBZ=2
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
								CASE 
									WHEN a.FBZYHSFDM=1 THEN d.MC
									WHEN a.FBZYHSFDM=3 THEN c.YHXM
									ELSE '暂未查询到发布者'
								END  as FBZXM
								from DATA_GWDMK a 
								left join DATA_DWDMK b on a.DWDM=b.DWDM
								left join DWYHK c on a.FBZ=c.YHM
								left join GLYDMK d on a.FBZ=d.DLZH
								left join GWFLK f on a.GWFL=f.ID
								left join SFDMK e on a.GZSF=e.SFDM
								where  a.QYDM=@QYDM
							else
								select a.*,b.GSMC,e.SFMC,f.FLMC,b.GSJJHTML,
									CASE 
										WHEN a.FBZYHSFDM=1 THEN d.MC
										WHEN a.FBZYHSFDM=3 THEN c.YHXM
										ELSE '暂未查询到发布者'
									END  as FBZXM
									from DATA_GWDMK a 
									left join DATA_DWDMK b on a.DWDM=b.DWDM
									left join DWYHK c on a.FBZ=c.YHM
									left join GLYDMK d on a.FBZ=d.DLZH
									left join GWFLK f on a.GWFL=f.ID
									left join SFDMK e on a.GZSF=e.SFDM
									where a.QYDM=@QYDM and a.SXBZ=@SXBZ
						end
				end
		end
	
END
GO


-- ----------------------------
-- Procedure structure for usp_Get_JCSJ
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_Get_JCSJ]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_Get_JCSJ]
GO

CREATE PROCEDURE [dbo].[usp_Get_JCSJ]  
AS  
BEGIN  
    /*  
        存储过程名称: usp_Get_All_Data  
        创建时间: 2024-12-06  
        修改记录:  
            
        描述:  
            用于获取系统基础数据表 ，包括: SFDMK, XLTTK, DWXZK, DWGMK, DWHYDMK 等。  
        
        返回了多个表的数据，每个表的数据会在一个单独的结果集中返回。  
    */  

    SET NOCOUNT ON;  
    BEGIN TRY  
        -- 获取 SFDMK 表   
        SELECT * FROM SFDMK;  
        -- 获取 XLTTK 表   
        SELECT * FROM XLTTK;  
        -- 获取 DWXZK 表   
        SELECT * FROM DWXZK; 
        -- 获取 DWGMK 表   
        SELECT * FROM DWGMK;  
        -- 获取 DWHYDMK 表   
        SELECT * FROM DWHYDMK;  
    END TRY  
    BEGIN CATCH  
        -- 错误处理  
        DECLARE @ErrorMessage NVARCHAR(4000);  
        DECLARE @ErrorSeverity INT;  
        DECLARE @ErrorState INT;  

        SELECT   
            @ErrorMessage = ERROR_MESSAGE(),  
            @ErrorSeverity = ERROR_SEVERITY(),  
            @ErrorState = ERROR_STATE();  

        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);  
    END CATCH  
END
GO


-- ----------------------------
-- Procedure structure for usp_GetZpjz
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetZpjz]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetZpjz]
GO

CREATE PROCEDURE [dbo].[usp_GetZpjz]
		@FBBZ int ,-- 发布标志 1.0 。2全部
	 
		@ISJUSTONE int ,--是否只获取一条招聘简章数据，@ISJUSTONE为1时，其他参数（除了@ZPJZID）无用
		@ZPJZID int ,-- 招聘简章ID，当@ISJUSTONE为1时有用

		@ISJUSTONEYH int, --是否只获取一个用户发布的， 
		@YHM nvarchar(50) ,-- 当@ISJUSTYH为1时，会用到此参数！
		@YHSFDM int,

		@ISJUSTONEDW int ,--是否通过单位代码的招聘简章
		@DWDM int  -- 单位代码
		as
BEGIN  
    /*  
		招聘简章数据-- 由管理员、单位用户来发布
        作用：获取招聘简章数据
        时间：2025年2月14日  
		实例： 
    */  

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
 
	if @FBBZ=2
		begin 
			if @ISJUSTONE=1  --只获取一条
				begin
					select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 3 then c.YHXM
						end as FBZMC,

						case a.CJZSFDM
							when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
							when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
						end as CJZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPJZK a
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where a.ID=@ZPJZID
				end

		   else	if @ISJUSTONEYH=1  -- 只获取一个用户的
				begin
				select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 3 then c.YHXM
					end as FBZMC,

					case a.CJZSFDM
						when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
						when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
					end as CJZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPJZK a
						left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.FBZ=@YHM and a.FBZSFDM=@YHSFDM 

				end
		   else if @ISJUSTONEDW=1  -- 通过单位代码获取招聘简章信息
				begin
					select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 3 then c.YHXM
					end as FBZMC,
					
					case a.CJZSFDM
						when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
						when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
					end as CJZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPJZK a
						left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.DWDM=@DWDM
				end

		 else	if @ISJUSTONE=0 and   @ISJUSTONEDW=0 and @ISJUSTONEYH=0 
					select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 3 then c.YHXM
					end as FBZMC,
					case a.CJZSFDM
						when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
						when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
					end as CJZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPJZK a
						left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM
				return 

		end 
		else
			begin 
				if @ISJUSTONE=1  --只获取一条
							select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 3 then c.YHXM
						end as FBZMC,
						
						case a.CJZSFDM
							when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
							when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
						end as CJZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPJZK a
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where a.ID=@ZPJZID

			   else	if @ISJUSTONEYH=1  -- 只获取一个用户的
						select a.*,
					case a.FBZSFDM
						when 1 then d.MC--管理员
						when 3 then c.YHXM
					end as FBZMC,
					
						case a.CJZSFDM
							when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
							when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
						end as CJZMC,
					f.DWMC,
					f.GSMC
					from DATA_ZPJZK a
						left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
						left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
						left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.FBZ=@YHM and a.FBZSFDM=@YHSFDM  and a.FBBZ=@FBBZ

				
			 else	if @ISJUSTONEDW=1
					begin 
						select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 3 then c.YHXM
						end as FBZMC,
						
						case a.CJZSFDM
							when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
							when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
						end as CJZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPJZK a
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM where  a.DWDM=@DWDM and a.FBBZ=@FBBZ
					end
				else	if @ISJUSTONE=0 and   @ISJUSTONEDW=0 and @ISJUSTONEYH=0
					select a.*,
						case a.FBZSFDM
							when 1 then d.MC--管理员
							when 3 then c.YHXM
						end as FBZMC,
						
						case a.CJZSFDM
							when 1 then (select MC from GLYDMK where DLZH=a.CJZ)
							when 3 then (select YHXM from DWYHK where YHM=a.CJZ)
						end as CJZMC,
						f.DWMC,
						f.GSMC
						from DATA_ZPJZK a
							left join DWYHK c on a.FBZ=c.YHM and a.FBZSFDM=3
							left join GLYDMK d on a.FBZ=d.DLZH and a.FBZSFDM=1
							left join DATA_DWDMK f on a.DWDM=f.DWDM and a.FBBZ=@FBBZ
					return 
			end 


 
		
END
GO


-- ----------------------------
-- Procedure structure for usp_LoginInterface
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_LoginInterface]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_LoginInterface]
GO

CREATE PROCEDURE [dbo].[usp_LoginInterface]  
    @Username NVARCHAR(50),  
    @Password NVARCHAR(50)  
AS  
BEGIN  
    /*  
        存储过程名称 : usp_LoginInterface  
        创建时间: 2024-12-04  
        修改记录:  
            - 2024-12-04: 创建了存储过程  
        描述:  
            登录接口，验证用户身份并返回角色信息  
        使用实例:  
            EXEC usp_LoginInterface @Username = 'example_user', @Password = 'example_pass';  
    */  
    SET NOCOUNT ON;  

    DECLARE @UserRole NVARCHAR(50);  -- 用户身份
    DECLARE @LoginSuccess BIT = 0; -- 成功标志  
	DECLARE @YHXM NVARCHAR(50)-- 用户姓名

    -- 检查学生表  select * from    DATA_STUDENT
    IF EXISTS (SELECT 1 FROM DATA_STUDENT WHERE YHM = @Username AND MM = @Password AND QYDM=1)  
    BEGIN  
        SET @UserRole = '学生';  
        SET @LoginSuccess = 1;  
		SET @YHXM=(select XSXM from DATA_STUDENT where YHM =@Username )
    END  

    -- 检查老师表   select * from   JSDMK 
    IF EXISTS (SELECT 1 FROM JSDMK WHERE DLZH = @Username AND DLMM = @Password AND QYDM=1)  
    BEGIN  
        SET @UserRole = '老师';  
        SET @LoginSuccess = 1;  
		SET @YHXM=(select JSMC from JSDMK where DLZH =@Username )
    END  

    -- 检查 select * from  DWYHK  单位用户库
    IF EXISTS (SELECT 1 FROM DWYHK WHERE  YHM= @Username AND MM = @Password  )  
    BEGIN  
        SET @UserRole = '单位用户';  
        SET @LoginSuccess = 1;  
		SET @YHXM=(select YHXM from DWYHK where YHM =@Username )
    END  

    -- 检查管理员表    select * from GLYDMK
    IF EXISTS (SELECT 1 FROM GLYDMK WHERE DLZH = @Username AND DLMM = @Password AND QYDM=1)  
    BEGIN  
        SET @UserRole = '管理员';  
        SET @LoginSuccess = 1;  
		SET @YHXM=(select MC from GLYDMK where DLZH =@Username )
    END  

    IF @LoginSuccess = 1  
    BEGIN  
     	-- 登录成功，返回用户角色  
        SELECT @LoginSuccess AS 'RESULT' , '登录成功' AS Msg,@Username AS 'YHM', @UserRole AS UserRole,@YHXM AS YHMC,
		(SELECT SFDM FROM YHSFDMK WHERE SFMC='管理员') AS 'YHSFDM';  
    
	
	END 
	
    ELSE  
    BEGIN  
        -- 登录失败  
        SELECT @LoginSuccess AS 'RESULT' , '登录失败' AS Msg,@Username AS 'YHM',  @UserRole AS 'UserRole',@YHXM AS YHMC,
		(SELECT SFDM FROM YHSFDMK WHERE SFMC='管理员') AS 'YHSFDM';  
    
    END  
END;
GO


