CREATE PROCEDURE [dbo].[usp_GetDwData]
	@BYDWYHM int , --是否通过单位用户名获取
	@DWYHM NVARCHAR(50), --单位用户名

	@BYDWDM int , --通过单位代码获取
	@DWDM  int 

AS
BEGIN
	 
	SET NOCOUNT ON;
 exec LuodengTable 'DATA_DWDMK'
 
	select a.* from DATA_DWDMK a
	 left join DWHYDMK b on a.DWHYDM=b.HYDM
	 left join DWXZK c on a.DWXZDM =c.DWXZDM
 
END
