-- ----------------------------
-- Procedure structure for usp_GetAllStudentData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetAllStudentData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetAllStudentData]
GO

CREATE PROCEDURE [dbo].[usp_GetAllStudentData]  
    @Username NVARCHAR(50),  
    @UserRole NVARCHAR(50)  
AS  
BEGIN  
    /*  
        存储过程名称 : usp_GetAllStudentData  
        创建时间: 2024-12-04  
        修改记录:  
            - 2024-12-04: 创建了存储过程  
        描述:  
            获取学生信息接口  
        使用实例:  
            EXEC [usp_GetAllStudentData] @Username, @UserRole;  
            -- 老师     获取 数据  
            -- 管理员   获取数据  
    */  
    
    SET NOCOUNT ON;  
   
    DECLARE @ISERROR INT = 0;  -- 是否错误标志  
    DECLARE @SFDM INT;   

    -- 检查用户角色是否存在  
    IF NOT EXISTS (SELECT 1 FROM YHSFDMK WHERE SFMC = @UserRole)  
    BEGIN  
        SET @ISERROR = 1;  -- 设置错误标志  
        SELECT 1 AS ISERROR, '用户身份不存在' AS MSG;  
        RETURN;  -- 返回，不执行后续查询  
    END  

    -- 获取用户角色的 SFDM  
    SELECT @SFDM = SFDM FROM YHSFDMK WHERE SFMC = @UserRole;  
	--select @SFDM '用户SFDM'
    -- 管理员角色（SFDM = 1）  
    IF (@SFDM = 1)  
    BEGIN  
        -- 查询所有学生信息  
        SELECT   
            a.[ID] AS '学生代码',  
            a.[XSXM] AS '学生姓名',  
            a.[XSXB] AS '性别',  
            a.[BIRTH] AS '出生日期',  
            DATEDIFF(YEAR, [BIRTH], GETDATE()) AS 年龄,  
            a.[YHM] AS '登录账号',  
            c.ZYMC AS '专业',  
            a.[SFZH] AS '身份证号',  
            a.[ZZMM] AS '政治面貌',  
            a.[SSNJ] AS '年级',  
            CASE a.[XZ]  
                WHEN 1 THEN '一年制'  
                WHEN 2 THEN '二年制'  
                WHEN 3 THEN '三年制'  
                WHEN 4 THEN '四年制'  
                WHEN 5 THEN '五年制'  
                WHEN 6 THEN '六年制（傻逼才读）'  
                ELSE '暂未提供'  
            END AS '学制',  
            a.[MZ] AS '民族',  
            a.[XSXH] AS '学号',  
            a.[BJMC] AS '班级',
			a.SSBJ as '班级代码',
			a.BJMC as '班级名称',
            b.XLMC AS '学历',  
            d.JYZT AS '就业状态',
			a.XSZP AS '学生照片',
			a.FZJS AS '负责教师',
			e.JSMC AS '教师名称'
        FROM   
            DATA_STUDENT a  
        LEFT JOIN   
            XLTTK b ON a.XLDM = b.ID  
        LEFT JOIN   
            ZYDMK c ON a.ZYDM = c.ID  
        LEFT JOIN   
            JYZTDMK d ON a.JYZT = d.ZTDM  
		LEFT JOIN 
		     JSDMK e ON a.FZJS=e.ID  --用于获取教师信息（姓名）
		where a.QYDM=1;
    END  
    -- 教师角色（SFDM = 2）  
    ELSE IF (@SFDM = 2)  
    BEGIN  
	--select 1
        -- 查询教师对应班级的学生信息  
        SELECT   
            a.[ID] AS '学生代码',  
            a.[XSXM] AS '学生姓名',  
            a.[XSXB] AS '性别',  
            a.[BIRTH] AS '出生日期',  
            DATEDIFF(YEAR, [BIRTH], GETDATE()) AS 年龄,  
            a.[YHM] AS '登录账号',  
            c.ZYMC AS '专业',  
            a.[SFZH] AS '身份证号',  
            a.[ZZMM] AS '政治面貌',  
            a.[SSNJ] AS '年级',  
            CASE a.[XZ]  
                WHEN 1 THEN '一年制'  
                WHEN 2 THEN '二年制'  
                WHEN 3 THEN '三年制'  
                WHEN 4 THEN '四年制'  
                WHEN 5 THEN '五年制'  
                WHEN 6 THEN '六年制（傻逼才读）'  
                ELSE '暂未提供'  
            END AS '学制',  
            a.[MZ] AS '民族',  
            a.[XSXH] AS '学号',  
            a.[BJMC] AS '班级', 
			a.SSBJ as '班级代码',
			a.BJMC as '班级名称',
            b.XLMC AS '学历',  
            d.JYZT AS '就业状态',
			a.XSZP AS '学生照片',
			a.FZJS AS '负责教师',
			e.JSMC AS '教师名称'
        FROM   
            DATA_STUDENT a  
        LEFT JOIN   
            XLTTK b ON a.XLDM = b.ID  
        LEFT JOIN   
            ZYDMK c ON a.ZYDM = c.ID  
        LEFT JOIN   
            JYZTDMK d ON a.JYZT = d.ZTDM   
		LEFT JOIN 
		     JSDMK e ON a.FZJS=e.ID  --用于获取教师信息（姓名）
        WHERE   
            SSBJ in (SELECT BJID FROM JSBJDYK WHERE JSID = (SELECT ID FROM JSDMK WHERE DLZH = @Username))
			and    a.QYDM=1;
    END  
    -- 如果不是管理员或教师  
    ELSE  
    BEGIN  
        SELECT 1 AS ISERROR, '用户无权限' AS MSG;  -- 返回权限不足的消息  
    END  
END;
GO


-- ----------------------------
-- Procedure structure for LuodengTable
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LuodengTable]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[LuodengTable]
GO

CREATE PROCEDURE [dbo].[LuodengTable]
	@objname nvarchar(256) = NULL		-- object name we're after
as
begin
	set nocount on
	set @objname=replace ( @objname , '[' , '' )
	set @objname=replace ( @objname , ']' , '' )
	-- @objname must be either sysobjects or systypes: first look in sysobjects
	declare @objid int
	declare @sysobj_type char(2)
	select @objid = object_id, @sysobj_type = type from sys.all_objects where object_id = object_id(@objname)
 
	if @objid is null
	begin
		return
	end
 
	SELECT 
    表名       = case when a.colorder=1 then d.name else '' end,
    表说明     = case when a.colorder=1 then isnull(f.value,'') else '' end,
    字段序号   = a.colorder,
    字段名     = a.name,
    字段说明   = isnull(g.[value],''),
    自增标识   = case when COLUMNPROPERTY( a.id,a.name,'IsIdentity')=1 then '√'else '' end,
    主键       = case when exists(SELECT 1 FROM sysobjects where xtype='PK' and parent_obj=a.id and name in (
                     SELECT name FROM sysindexes WHERE indid in( SELECT indid FROM sysindexkeys WHERE id = a.id AND colid=a.colid))) then '√' else '' end,
    类型       = b.name,
    占用字节数 = a.length,
    长度       = COLUMNPROPERTY(a.id,a.name,'PRECISION'),
    小数位数   = isnull(COLUMNPROPERTY(a.id,a.name,'Scale'),0),
    允许空     = case when a.isnullable=1 then '√'else '' end,
    默认值     = isnull(e.text,'')
FROM 
    syscolumns a
left join 
    systypes b 
on 
    a.xusertype=b.xusertype
inner join 
    sysobjects d 
on 
    a.id=d.id  and d.xtype='U' and  d.name<>'dtproperties'
left join 
    syscomments e 
on 
    a.cdefault=e.id
left join 
sys.extended_properties   g 
on 
    a.id=G.major_id and a.colid=g.minor_id  
left join
sys.extended_properties f
on 
    d.id=f.major_id and f.minor_id=0
where 
    d.name=@objname  
order by 
    a.id,a.colorder
	-- DISPLAY COLUMN IF TABLE / VIEW
	
/*	-- DISPLAY TABLE INDEXES & CONSTRAINTS
	if @sysobj_type in ('S ','U ')
	begin
		print ' '
		EXEC sys.sp_helpindex @objname
		print ' '
		EXEC sys.sp_helpconstraint @objname,'nomsg'
		if (select count(*) from sys.objects obj, sysdepends deps
			where obj.type ='V' and obj.object_id = deps.id and deps.depid = @objid and deps.deptype = 1) = 0
		begin
			raiserror(15647,-1,-1,@objname) -- No views with schemabinding reference table '%ls'.
		end
		else
		begin
			select distinct 'Table is referenced by views' = obj.name from sys.objects obj, sysdepends deps
				where obj.type ='V' and obj.object_id = deps.id and deps.depid = @objid
					and deps.deptype = 1 group by obj.name
		end
	end
	else if @sysobj_type in ('V ')
	begin
		print ' '
		raiserror(15469,-1,-1,@objname) -- No constraints defined
		print ' '
		raiserror(15470,-1,-1,@objname) -- No foreign keys reference table '%ls'.
		EXEC sys.sp_helpindex @objname
	end
	*/
end
GO


-- ----------------------------
-- Procedure structure for LuoDeng_getAlltableInfo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LuoDeng_getAlltableInfo]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[LuoDeng_getAlltableInfo]
GO

CREATE PROCEDURE [dbo].[LuoDeng_getAlltableInfo]  
AS  
BEGIN  
    SET NOCOUNT ON;  -- 防止返回受影响的行数，提升性能  
	/*
	获取表部分信息
	*/


    SELECT   
        t.name AS '表名',  
        ep.value AS '表备注',  
        COUNT(c.column_id) AS '字段数量'  
    FROM   
        sys.tables t   
    JOIN   
        sys.columns c ON t.object_id = c.object_id  
    LEFT JOIN   
        sys.extended_properties ep ON ep.major_id = t.object_id AND ep.minor_id = 0 AND ep.name = 'MS_Description'  
    WHERE   
        t.is_ms_shipped = 0  -- 过滤掉系统表  
    GROUP BY  
        t.name, ep.value  -- 必须包含所有非聚合列  
    ORDER BY   
        t.name;  
END;
GO


-- ----------------------------
-- Procedure structure for usp_StudengLogin
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_StudengLogin]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_StudengLogin]
GO

CREATE PROCEDURE [dbo].[usp_StudengLogin]
	@Username NVARCHAR(50),  
    @Password NVARCHAR(50) 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	 

    -- 检查学生表  select * from    DATA_STUDENT
	
	 IF EXISTS (SELECT 1 FROM DATA_STUDENT WHERE YHM = @Username)  
	    
		IF EXISTS (SELECT 1 FROM DATA_STUDENT WHERE YHM = @Username AND MM = @Password AND QYDM=1)  
			 BEGIN  
					BEGIN  
						SELECT  1 AS 'RESULT' , '登录成功' AS 'Msg',@Username AS 'YHM',  '学生' AS 'UserRole',(SELECT XSXM FROM DATA_STUDENT WHERE YHM=@Username) AS YHMC,
						(SELECT SFDM FROM YHSFDMK WHERE SFMC='学生') AS 'YHSFDM';
		    		END 
			 END
		ELSE  
			IF ((SELECT QYDM FROM DATA_STUDENT WHERE YHM = @Username)=0)
				BEGIN  
			    	-- 登录失败  
		        	SELECT  0 AS 'RESULT' , '账户已被禁用' AS 'Msg',@Username AS 'YHM',  '学生' AS 'UserRole',(SELECT XSXM FROM DATA_STUDENT WHERE YHM=@Username) AS YHMC,
					(SELECT SFDM FROM YHSFDMK WHERE SFMC='学生') AS 'YHSFDM';  
				END 
			ELSE
				BEGIN  
					-- 登录失败  
					  SELECT  0 AS 'RESULT' , '密码错误' AS 'Msg',@Username AS 'YHM',  '学生' AS 'UserRole',(SELECT XSXM FROM DATA_STUDENT WHERE YHM=@Username) AS YHMC,
					  (SELECT SFDM FROM YHSFDMK WHERE SFMC='学生') AS 'YHSFDM';  
				END  

	ELSE  
			BEGIN  
				-- 登录失败  
				  SELECT  0 AS 'RESULT' , '用户不存在' AS 'Msg',@Username AS 'YHM', Null AS 'UserRole',(SELECT XSXM FROM DATA_STUDENT WHERE YHM=@Username) AS YHMC,
				  (SELECT SFDM FROM YHSFDMK WHERE SFMC='学生') AS 'YHSFDM';  
    
			END  
END
GO


-- ----------------------------
-- Procedure structure for usp_getXscjdK
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_getXscjdK]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_getXscjdK]
GO

CREATE PROCEDURE [dbo].[usp_getXscjdK]  
		@QYDM int, -- 启用代码 1.0 。2全部
		@YHSFDM int, --用户身份代码
        @YHM nvarchar(50) ,--用户名
		@STUID int --学生ID ，当单位、教师、管理员用户只获取一条数据时就会用到这个
		-- 当@STUID不等于-1时，则是获取单个学生的成绩
		--学生使用@YHM来获取成绩
		as
BEGIN  
    /*  
        作用：获取学生成绩
        时间：2025年2月14日  
		实例：exec usp_getXscjdK 2,2,'lls',-1
			  exec usp_getXscjdK 2,4,'1',-1
    */  
	--select FZJS from DATA_STUDENT

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	if @STUID<>-1 
			if @QYDM=2
	
					select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where a.STUID=@STUID
			else
					select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where a.STUID=@STUID and a.QYDM=@QYDM
	else
		begin
			if @YHSFDM=4 --学生只能看自己的·
					begin 
						if @QYDM=2 -- 获取全部的
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where b.YHM=@YHM
						else
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where a.QYDM=@QYDM and  b.YHM=@YHM
						end
			if @YHSFDM=1 --管理员看所有
					begin
						if @QYDM=2 -- 获取全部的
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
						else
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where a.QYDM=@QYDM
						end
			if @YHSFDM=2
					begin
						if @QYDM=2 -- 获取全部的
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where 
								-- 教师可以看自己对应的班级的学生的成绩
								b.SSBJ in (select f.BJID from JSBJDYK f where f.JSID=(select g.ID from JSDMK g where g.DLZH=@YHM) )
						else
							select a.*,b.XSXM,b.XSXH,b.XSZP,c.BJMC,d.ZYMC,e.JSMC from XSCJDK a 
								left join DATA_STUDENT b on a.STUID=b.ID
								left join BJDMK c on b.SSBJ=c.ID
								left join ZYDMK d on c.ZYDM=d.ID
								left join JSDMK e on b.FZJS=e.ID
								where a.QYDM=@QYDM and 
								-- 教师可以看自己对应的班级的学生的成绩
								b.SSBJ in (select f.BJID from JSBJDYK f where f.JSID=(select g.ID from JSDMK g where g.DLZH=@YHM) )
						end
		end

	
		
END
GO


-- ----------------------------
-- Procedure structure for usp_getXxdmkData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_getXxdmkData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_getXxdmkData]
GO

CREATE PROCEDURE [dbo].[usp_getXxdmkData]
	@UserRole int , -- 对照YHSFDMK.ID 
	@YHM NVARCHAR(50) --用户名
AS
BEGIN  
    /*  
	  各种用户获取消息信息 
	*/  
	--select* from YHSFDMK
	--select* from XXDMK
    DECLARE @CFZSFDM NVARCHAR(50);  -- 触发者身份代码
	DECLARE @JSZSFDM NVARCHAR(50);  -- 接收者身份代码
 
    IF @UserRole = 1  -- 管理员：获取全部的消息即可 
		BEGIN  
		  select 
		  a.ID,
			a.CFZ,
			CFZSFDM,
			JSZSFDM,
			 case a.CFZSFDM 
				when 3 then (select YHXM from DWYHK where YHM=CFZ) -- 触发者是单位
				when 4 then (select XSXM from DATA_STUDENT where YHM=CFZ) -- 触发者是学生
			end as CFZXM, --姓名
			a.CFZXW,
			a.JSZ,
			case a.JSZSFDM 
				when 3 then (select YHXM from DWYHK where YHM=JSZ) -- 接收者是单位
				when 4 then (select XSXM from DATA_STUDENT where YHM=JSZ) -- 接收者是学生
			end as JSZXM, --姓名	
			DZNR,-- 动作内容
			YDBZ,
			CFSJ
			from XXDMK a
			/*
			 left join DATA_STUDENT b on a.CFZ=b.YHM or a.JSZ=b.YHM
			 left join DWYHK c on a.CFZ=c.YHM  or a.JSZ=b.YHM  --使用left join 匹配，匹配不到也能显示出该XXDMK的信息
			*/
			order by a.CFSJ desc
		END
	ELSE IF @UserRole = 2  -- 老师用户无权限（暂时不涉及）
		BEGIN 
			select '老师用户暂无权限查看消息' error
		END
	ELSE IF @UserRole = 3 or  @UserRole = 4 --单位用户或者学生
		BEGIN 
		  -- 获取触发者用户身份代码、接收者身份代码
		  select @CFZSFDM=CFZSFDM,@JSZSFDM=JSZSFDM from XXDMK
		  
			SELECT   
				a.CFZ,  
				CFZSFDM,
				JSZSFDM,
				CASE a.CFZSFDM   
					WHEN 3 THEN c.YHXM -- 触发者是单位  
					WHEN 4 THEN b.XSXM -- 触发者是学生  
				END AS CFZXM, -- 姓名  
				a.CFZXW,  
				CASE a.CFZSFDM
					WHEN 3 THEN c.YHZP -- 触发者是单位  
					WHEN 4 THEN b.XSZP -- 触发者是学生  
				END AS YHZP, -- 照片
				a.JSZ,  
				CASE a.JSZSFDM   
					WHEN 3 THEN c.YHXM -- 接收者是单位  
					WHEN 4 THEN b.XSXM -- 接收者是学生  
				END AS JSZXM, -- 姓名    
				a.DZNR, -- 动作内容  
				a.YDBZ,  
				a.DZLX,  
				a.CFSJ  
			FROM XXDMK a  
			LEFT JOIN DATA_STUDENT b ON a.CFZ = b.YHM OR a.JSZ = b.YHM  
			LEFT JOIN DWYHK c ON a.CFZ = c.YHM OR a.JSZ = c.YHM  -- 这里改正为 c.YHM  
			WHERE a.CFZ = @YHM OR a.JSZ = @YHM OR a.QBBZ = 1   
			ORDER BY a.CFSJ DESC;
		END
	ELSE 
	  BEGIN
		select '无效身份 ' error
	  END
END
GO


-- ----------------------------
-- Procedure structure for usp_AllUserGetXtgg
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_AllUserGetXtgg]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_AllUserGetXtgg]
GO

CREATE PROCEDURE [dbo].[usp_AllUserGetXtgg]  
	 @QYDM int ,--1 只获取启用的，0 只获取不启用的 ，-1获取全部 
	 @JUSTONE int, -- 1 只获取一条，0 获取多一条
	 @GGID int  -- 公告ID，当@JUSTONE为1时才会用到
AS  
BEGIN  
    /*  
        作用：获取招聘公告信息： XTGGK，
        时间：2025年3月11日  
		只有 管理员可以发布系统公告
 
		ID	
		GGBT		公告标题
		GGNR		公告内容
		GGNRHTML	公司内容HTML
		QYDM		启用代码
		CJSJ		创建时间
		FBZ			发布者
		FBZSFDM		发布者省身份代码
		LLL			浏览量
		GGLX		公告类型
    */  
	--select * from XTGGK
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	--select * from YHSFDMK
	if @JUSTONE=1
			select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from XTGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.ID=@GGID
	else
		begin
			if @QYDM=-1
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from XTGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
			else
				select a.*,
					CASE a.FBZSFDM
					 WHEN 1 THEN  d.MC --管理员
					 WHEN 2 THEN  c.JSMC -- 教师
					 WHEN 3 THEN b.YHXM-- 单位
				   END AS FBZXM ,--发布者姓名
				   	CASE a.FBZSFDM
					 WHEN 1 THEN  '管理员' --管理员
					 WHEN 2 THEN  '教师' -- 教师
					 WHEN 3 THEN 'HR'-- 单位
				   END AS FBZSF --发布者身份
				from XTGGK a 
						left join DWYHK b on a.FBZ=b.YHM
						left join JSDMK c on a.FBZ=c.DLZH
						left join GLYDMK d on a.FBZ=d.DLZH
						where a.QYDM=@QYDM
			end

END
GO


