CREATE PROCEDURE [dbo].[usp_GetStudentXmcg]  
	@QYDM int,-- 1获取启用，0 获取未启用，2获取全部
	@ISGETALL int, --1 获取全部学生的，0 获取指定学生的
	@STUID int --当@ISGETALL为0 时该参数用于获取指定学生
AS  
BEGIN  
    /*  
        作用：获取学生项目成果
        时间：2025年3月15日  
		exec usp_GetStudentXmcg 2,1,1237
    */  
	if @ISGETALL=0
		begin 
		  if @QYDM=2
				select a.*,
						b.XSXM,b.XSZP,b.XSXH,b.XSXB,
						c.BJMC,b.BJMC,d.ZYMC,d.ZYLB
					from XMCGK a -- 项目成果库
						left join DATA_STUDENT b on a.STUID=b.ID
						left join BJDMK c on b.SSBJ=c.ID
						left join ZYDMK d on c.ZYDM=d.ID
					where b.ID=@STUID
			else
				select a.*,
						b.XSXM,b.XSZP,b.XSXH,b.XSXB,
						c.BJMC,b.BJMC,d.ZYMC,d.ZYLB
					from XMCGK a -- 项目成果库
						left join DATA_STUDENT b on a.STUID=b.ID
						left join BJDMK c on b.SSBJ=c.ID
						left join ZYDMK d on c.ZYDM=d.ID
					where b.ID=@STUID and a.QYDM=@QYDM
		end
	else
		begin 
		  if @QYDM=2
				select a.*,
						b.XSXM,b.XSZP,b.XSXH,b.XSXB,
						c.BJMC,b.BJMC,d.ZYMC,d.ZYLB
					from XMCGK a -- 项目成果库
						left join DATA_STUDENT b on a.STUID=b.ID
						left join BJDMK c on b.SSBJ=c.ID
						left join ZYDMK d on c.ZYDM=d.ID
			else
				select a.*,
						b.XSXM,b.XSZP,b.XSXH,b.XSXB,
						c.BJMC,b.BJMC,d.ZYMC,d.ZYLB
					from XMCGK a -- 项目成果库
						left join DATA_STUDENT b on a.STUID=b.ID
						left join BJDMK c on b.SSBJ=c.ID
						left join ZYDMK d on c.ZYDM=d.ID
					where  a.QYDM=@QYDM
		end


END
GO


-- ----------------------------
-- Procedure structure for usp_getWaitDoMS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_getWaitDoMS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_getWaitDoMS]
GO

CREATE PROCEDURE [dbo].[usp_getWaitDoMS]  
	@UserRole int, -- 用户角色 ，1管理员 2 教师 3 单位用户 4 学生
	@YHM NVARCHAR(50)-- 用户名
AS  
BEGIN  
    /*  
        作用：获取待安排面试的列表
        时间：2025年2月14日  
    */  

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON; 
	select * from MSDMK
	if @UserRole=1
		begin 
			-- 管理员获取全部
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,
			d.DWMC
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
		-- 不考虑老师发布岗位的情况
		end
	else if  @UserRole=3 --单位用户
		begin 
			-- 单位用户只能看自己发布的！
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			 c.YHXM FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,
			d.DWMC
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
			where a.FQZ=@YHM
		-- 不考虑老师发布岗位的情况
		end


	exec LuodengTable 'DATA_DWDMK_luodeng' -- 面试代码库
	select * from DATA_GWDMK
END
GO


