CREATE PROCEDURE [dbo].[usp_getMsData]  
	@UserRole int, -- 用户角色 ，1管理员 2 教师 3 单位用户 4 学生
	@YHM NVARCHAR(50)-- 用户名
AS  
BEGIN  
    /*  
        作用：各个用户获取面试数据
        时间：2025年2月14日  
    */  

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON; 
	--select * from MSDMK
	if @UserRole=1
		begin 
			-- 管理员获取全部
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			--a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,
			b.XSXH,
			d.DWMC,
			j.MSJG,
			a.MSPJ,
			a.HRZJ
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
				left join MSJGDMK j on j.ID=a.MSJG
		-- 不考虑老师发布岗位的情况
		end
	else if  @UserRole=3 --单位用户
		begin 
			-- 单位用户只能看自己发布的！
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
		--	a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			 c.YHXM FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,
			d.DWMC,
			b.XSXH,
			b.XSXM,
			b.XSXB,
			b.BIRTH,
			b.SSBJ,
			b.BJMC,
			b.SSNJ,
			b.ZZMM,
			b.JYZT,
			b.XSZP,
			b.FZJS,
			f.JSMC FZJSMC,
			b.MZ,
			a.MSPJ,
			a.HRZJ,
			j.MSJG
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join JSDMK f on b.FZJS=f.ID
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join MSJGDMK j on j.ID=a.MSJG
			where a.FQZ=@YHM
		-- 不考虑老师发布岗位的情况
		end
	else if @UserRole=2 --教师用户
		begin 
			-- 教师查看自己管理的学生的
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
		--	a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			 c.YHXM FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,
			d.DWMC,
			b.XSXM,
			b.XSXH,
			b.XSXB,
			b.BIRTH,
			b.SSBJ,
			b.BJMC,
			b.SSNJ,
			b.ZZMM,
			b.JYZT,
			b.XSZP,
			b.FZJS,
			f.JSMC FZJSMC,
			b.MZ,
			a.MSPJ,
			a.HRZJ,
			j.MSJG
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join JSDMK f on b.FZJS=f.ID
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join MSJGDMK j on j.ID=a.MSJG
				left join JSBJDYK i on b.SSBJ=i.BJID
			where i.JSID=(select ID from JSDMK where DLZH=@YHM)
		-- 不考虑老师发布岗位的情况
		end

	--exec LuodengTable 'DATA_DWDMK_luodeng' -- 面试代码库
	--select * from DATA_GWDMK
END
GO


-- ----------------------------
-- Procedure structure for usp_ClearDuplicates
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_ClearDuplicates]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_ClearDuplicates]
GO

CREATE PROCEDURE [dbo].[usp_ClearDuplicates]  
AS  
BEGIN  
    -- SET NOCOUNT ON added to prevent extra result sets from  
    -- interfering with SELECT statements.  
    SET NOCOUNT ON;  

    -- 使用公共表表达式 (CTE) 来识别重复记录  
    WITH CTE AS (  
        SELECT   
            *,  
            ROW_NUMBER() OVER (PARTITION BY JSID, BJID ORDER BY (SELECT NULL)) AS RowNum  
        FROM   
            JSBJDYK  
    )  
    -- 删除重复记录，只保留每组的第一条记录  
    DELETE FROM CTE WHERE RowNum > 1;  

    -- 可选：返回受影响的行数  
    SELECT @@ROWCOUNT AS DeletedRows;  
END
GO


