CREATE PROCEDURE [dbo].[usp_GetXsxxk]
		@BYYHM int ,
		@YHM nvarchar(50),
		@STUID int
		as
BEGIN  
    /*  
		
        作用：获取学生信息 XSXXK数据
        时间：2025年2月14日  
		实例： exec usp_GetXsxxk 1,'20183014062',-1
    */  
	--exec LuodengTable 'XSXXK'

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  

	select a.*,b.SSNJ,b.SSBJ,b.XSXB,b.XSXM,b.YHM,b.FZJS,b.XSXH into #temp FROM XSXXK a
		left join DATA_STUDENT b on a.STUID=b.ID

		if @BYYHM=1 
			select * from #temp where  YHM=@YHM 
		else
			select * from #temp  where STUID=@STUID

		DROP TABLE #temp;

END
GO


-- ----------------------------
-- Procedure structure for usp_getWaitAddMS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_getWaitAddMS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_getWaitAddMS]
GO

CREATE PROCEDURE [dbo].[usp_getWaitAddMS]  
	@YHM NVARCHAR(50)-- 用户名
AS  
BEGIN  
    /*  
        作用：单位用户获取待安排的面试
        时间：2025年2月14日  
		获取方式：从TDJLK 中获取、从MSSQK中获取待面试的数据
    */  

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;
	-- 暂时先从TDJLK获取
	SELECT a.*,
		b.SSBJ,b.XSXM,b.BJMC,b.ID STUID,b.SSNJ,b.XLDM,d.XLMC,b.XSXB,b.XSZP,b.FZJS,b.XSXH,b.ZZMM,
			c.ID GWDM,c.GWMC,c.TDSM,c.FBZ,h.BJMC,h.BZRDM,i.JSMC BZRXM,
			e.GSMC,
			f.YHXM
		FROM TDJLK a
		left join DATA_STUDENT b on a.STUID=b.ID
		left join BJDMK h on b.SSBJ=h.ID
		left join JSDMK i on h.BZRDM=i.ID
		left join DATA_GWDMK c on a.GWDM=c.ID
		left join XLTTK d on b.XLDM=d.ID
		left join DATA_DWDMK e on c.DWDM=e.DWDM 
		left join DWYHK f on c.FBZ= f.YHM 
		where TDJG=2 and a.DWYH=@YHM and a.ISMS=0
	
END
GO


-- ----------------------------
-- Procedure structure for usp_StuGetWaitMsData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_StuGetWaitMsData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_StuGetWaitMsData]
GO

CREATE PROCEDURE [dbo].[usp_StuGetWaitMsData]  
	@YHM NVARCHAR(50)-- 用户名
AS  
BEGIN  
    /*  
        作用：学生用户获取待确认的面试
        时间：2025年2月14日  
		获取方式：从MSDMK: QYDM=1, QRDM=0,MSZT=1（默认值就是1）
    */  
	--exec LuodengTable 'MSDMK'
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,-- 公司名称
			d.DWMC, -- 单位名称
			d.GZDD, -- 工作地点
			h.LOGO --单位logo
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
			where a.XSDM=(select ID from DATA_STUDENT where YHM=@YHM) and a.QRDM=0 and a.QYDM=1
END
GO


-- ----------------------------
-- Procedure structure for usp_GetTjGwData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetTjGwData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetTjGwData]
GO

CREATE PROCEDURE [dbo].[usp_GetTjGwData]
		@YHM nvarchar(50),
		@YHSFDM int 
		as
BEGIN  
    /*  
		
        作用：获取推荐的岗位信息
        时间：2025年2月14日  
		实例： 
		解释：学生获取（所属范围），教师获取（自己发布的），管理员获取（全部）
    */  
	--exec LuodengTable 'XSXXK'

    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	if @YHSFDM=2 --是教师获取，获取自己发布的
			select a.*,
			b.*,
			e.XLMC,
			e.XLMS,
			case 
				when a.TJRSFDM=2 then  c.JSMC
				when a.TJRSFDM=1 then d.MC
			end as 'TJRXM', -- 推荐人姓名
			(select count(*) from TJDXK where TJDM =a.ID ) as 'SJDXSL', -- 涉及对象数量
			(select count(*) from TJDXK where TJDM =a.ID and DXLX=1 ) as 'ZDXSSL', -- 针对学生数量
			(select count(*) from TJDXK where TJDM =a.ID and DXLX=2 ) as 'ZDBJSL' -- 针对班级数量
			from TJGWK a 
				left join DATA_GWDMK b on a.GWDM=b.ID and b.QYDM=1
				left join JSDMK c on a.TJR=c.DLZH and a.TJRSFDM=2
				left join GLYDMK d on a.TJR=d.DLZH and a.TJRSFDM=1
				left join XLTTK e on b.ZDXLYQ =e.ID
			 where a.TJR=@YHM and a.TJRSFDM=@YHSFDM
		if @YHSFDM=4 --学生获取，只获取涉及自己的
			select a.*,
			b.*,
			e.XLMC,
			e.XLMS,
			case 
				when a.TJRSFDM=2 then  c.JSMC
				when a.TJRSFDM=1 then d.MC
			end as 'TJRXM', -- 推荐人姓名
			(select count(*) from TJDXK where TJDM =a.ID ) as 'SJDXSL', -- 涉及对象数量
			(select count(*) from TJDXK where TJDM =a.ID and DXLX=1 ) as 'ZDXSSL', -- 针对学生数量
			(select count(*) from TJDXK where TJDM =a.ID and DXLX=2 ) as 'ZDBJSL' -- 针对班级数量
			from TJGWK a 
				left join DATA_GWDMK b on a.GWDM=b.ID and b.QYDM=1
				left join JSDMK c on a.TJR=c.DLZH and a.TJRSFDM=2
				left join GLYDMK d on a.TJR=d.DLZH and a.TJRSFDM=1 
				left join XLTTK e on b.ZDXLYQ =e.ID
			 where  a.ID in (select TJDM FROM TJDXK where DXLX=1 and DXDM=(select id from DATA_STUDENT where YHM=@YHM) ) or
			        a.ID in (select TJDM FROM TJDXK where DXLX=2 and DXDM=(select SSBJ from DATA_STUDENT where YHM=@YHM) )


	--exec LuodengTable 'TJDXK'
	--exec LuodengTable 'TJGWK'
	--exec LuodengTable 'DATA_GWDMK'
 
END
GO


-- ----------------------------
-- Procedure structure for LuodengClearCF
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LuodengClearCF]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[LuodengClearCF]
GO

CREATE PROCEDURE [dbo].[LuodengClearCF]  
    @TableName NVARCHAR(128),  
    @ColumnName NVARCHAR(128)  
AS  
BEGIN  
    DECLARE @SQL NVARCHAR(MAX)  

    -- 动态 SQL 语句，用于删除重复记录  
    SET @SQL = N'  
    WITH CTE AS (  
        SELECT *,  
               ROW_NUMBER() OVER (PARTITION BY ' + QUOTENAME(@ColumnName) + ' ORDER BY (SELECT NULL)) AS RowNum  
        FROM ' + QUOTENAME(@TableName) + '  
    )  
    DELETE FROM CTE WHERE RowNum > 1;'  

    -- 执行动态 SQL  
    EXEC sp_executesql @SQL  
END
GO


-- ----------------------------
-- Procedure structure for usp_GetMsData_StuAndDw
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetMsData_StuAndDw]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetMsData_StuAndDw]
GO

CREATE PROCEDURE [dbo].[usp_GetMsData_StuAndDw]  
	@TYPE INT,
	@YHM NVARCHAR(50)-- 学生用户名
AS  
BEGIN  
    /*  
        作用：学生用户获取待确认的面试
        时间：2025年2月14日  
		获取方式：从MSDMK: QYDM=1, QRDM=0,MSZT=1（默认值就是1）
    */  
	--exec LuodengTable 'MSDMK'
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;
	IF @TYPE=0  --只获取待确认的面试 学生
		BEGIN 
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,-- 公司名称
			d.DWMC, -- 单位名称
			d.GZDD, -- 工作地点
			h.LOGO --单位logo
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
			where a.XSDM=(select ID from DATA_STUDENT where YHM=@YHM) and a.QRDM=0 and a.QYDM=1
		END
	IF @TYPE=1 -- 单位获取待开始的面试 MSZT=2  
		BEGIN
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,-- 公司名称
			d.DWMC, -- 单位名称
			d.GZDD, -- 工作地点
			h.LOGO --单位logo
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
			where   a.QRDM=1 and a.QYDM=1 and a.MSZT=2 --学生已确认，待开始面试
		END
	IF @TYPE=3 --学生获取所有与其相关的面试数据 
		BEGIN
			select 
			a.MSDM,--面试代码
			a.XSDM,--学生代码
			a.DWDM,--单位代码
			a.GWDM,--岗业代码
			a.MSSJ,--	面试时间
			a.MSZT,--面试状态：1单位已安排（待学生确认），2学生已确认，3开始面试（面试中，待单位用户关闭）4 面试关闭（待录入结果） 5已录入结果 
			a.MSJG,--面试结果,MSJGDMK.ID
			a.FQZ,--发起者用户名
			CASE FQZSFDM  
				WHEN 1 THEN e.MC  -- 管理员
				WHEN 3 THEN c.YHXM  -- 单位用户
				ELSE 'get out name！'  
			END AS FQZXM,  -- 发起者姓名
			a.FQZSFDM,--发起者身份代码
			a.FQSJ,--发起时间，默认(getdate())
			a.QYDM,--启用代码
			a.QRDM,--确认代码，即学生是否确认了面试
			a.MSDD,--面试地点
			d.GWMC,-- 岗位名称
			d.TDSM, -- 投递说明
			h.GSMC,-- 公司名称
			d.DWMC, -- 单位名称
			d.GZDD, -- 工作地点
			h.LOGO --单位logo
			from MSDMK a
				left join DATA_STUDENT b on a.XSDM=b.ID
				left join DWYHK c on a.FQZ=c.YHM
				left join DATA_DWDMK h on a.DWDM=h.DWDM
				left join DATA_GWDMK d on a.GWDM=d.ID
				left join GLYDMK e on a.FQZ=e.DLZH -- 可能是管理员发布的岗位，用于获取发布者姓名
			where a.XSDM=(select ID from DATA_STUDENT where YHM=@YHM) and  a.QYDM=1 
				order by a.MSZT asc
		END
	IF @TYPE=4
		BEGIN
			return
		END
END
GO


-- ----------------------------
-- Procedure structure for usp_GetDhjl
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetDhjl]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetDhjl]
GO

CREATE PROCEDURE [dbo].[usp_GetDhjl]  
	@YHM nvarchar(50),-- 当前用户
	@YHSFDM INT ,--当前用户身份代码
	@LYYHM nvarchar(50),-- 另一用户名
	@LYYHSFDM int-- 另一用户身份代码
	AS  
BEGIN  
    /*  
        作用：获取实时通讯对话记录： 只获取一条
        时间：2025年3月16日
		 
    */  
	--exec LuodengTable 'LXRK'
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;  
	select a.*,h.DWMC,h.GSMC,b.YHXM DWYHMC,--单位用户名称
		CASE  @YHSFDM
			WHEN 1 THEN d.MC --当前是管理员  
			WHEN 2 THEN e.JSMC --当前是教师
			WHEN 4 THEN c.XSXM --当前是学生
		END AS DQYHXM,  --当前用户姓名
		CASE  @YHSFDM
			WHEN 1 THEN '管理员暂无照片' --当前是管理员  
			WHEN 2 THEN '老师暂无照片' --当前是教师
			WHEN 3 THEN  b.YHZP --另一个是单位
			WHEN 4 THEN c.XSZP --当前是学生
		END AS DQYHZP,  --当前用户照片，教师和管理员未上线照片


		CASE  @LYYHSFDM
			WHEN 1 THEN d.MC  --另一个是管理员  
			WHEN 2 THEN e.JSMC --另一个是教师
			WHEN 4 THEN c.XSXM --另一个是学生
		END AS LYYHXM, -- 另一用户姓名
		CASE  @LYYHSFDM
			WHEN 1 THEN '管理员暂无照片' --另一个是管理员  
			WHEN 2 THEN '老师暂无照片' --另一个是教师
			WHEN 3 THEN  b.YHZP --另一个是单位
			WHEN 4 THEN c.XSZP --另一个是学生
		END AS LYYHZP -- 另一用户姓名

	from DHJLK a
		left join DWYHK b on b.YHM=a.FROMYHM or b.YHM=a.TOYHM
		left join DATA_STUDENT c on c.YHM=a.FROMYHM or c.YHM=a.TOYHM
		left join GLYDMK d on d.DLZH=a.FROMYHM or d.DLZH=a.TOYHM
		left join JSDMK e  on e.DLZH    =a.FROMYHM or e.DLZH=a.TOYHM
 		left join DATA_DWDMK h on b.SSDW= h.DWDM 
	where ( a.TOYHM=@LYYHM and a.FROMYHM=@YHM) or (a.TOYHM=@YHM and a.FROMYHM= @LYYHM)
END
GO


-- ----------------------------
-- Procedure structure for usp_GetUserData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GetUserData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GetUserData]
GO

CREATE PROCEDURE [dbo].[usp_GetUserData]  
	@YHM nvarchar(50),-- 当前用户
	@YHSFDM INT --当前用户身份代码
	AS  
BEGIN  
    /*  
        作用：获取系统用户信息
        时间：2025年3月16日
		 
    */  
	--exec LuodengTable 'LXRK'
    -- 防止额外结果集干扰SELECT语句  
    SET NOCOUNT ON;
	if @YHSFDM=4 --学生
		select a.YHM, 4 YHSFDM,a.XSXM YHXM,a.XSZP YHZP  from DATA_STUDENT a  where a.YHM=@YHM
	if @YHSFDM=3 --单位
		select a.YHM, 3 YHSFDM,a.YHXM ,a.YHZP,b.GSMC,a.ZW from DWYHK a 
			left join DATA_DWDMK b on a.SSDW=b.DWDM
				where a.YHM=@YHM
	if @YHSFDM=2 --教师
		select a.DLZH YHM,2 YHSFDM, a.JSMC ,'教师暂无照片' as YHZP from JSDMK a where a.DLZH=@YHM
		 
END
GO


-- ----------------------------
-- Procedure structure for getStudentDataNewInterface
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[getStudentDataNewInterface]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[getStudentDataNewInterface]
GO

CREATE PROCEDURE [dbo].[getStudentDataNewInterface]  
    @yhsfdm int,  -- 用户身份代码
	@qydm int, -- 启用代码
    @yhm NVARCHAR(50)   -- 用户名
 
AS  
BEGIN  
    /*  
        存储过程名称 : [getStudentDataNewInterface]  
        创建时间: 2025-3-29
        修改记录:  
            - 2024-12-04: 创建了存储过程  
        描述:  
            获取学生信息接口  (新版，支持英文字段)
        使用实例:  
		 exec getStudentDataNewInterface 3, 2, 'lls' 
    */  
    
    SET NOCOUNT ON;  
	IF @yhsfdm=3 -- 教师
		begin
			if @qydm=2 --获取全部
				 -- 查询所有学生信息  
				SELECT   
					a.[ID],  a.[XSXM],  a.[XSXB],  a.[BIRTH],  
					DATEDIFF(YEAR, [BIRTH], GETDATE()) AS NL,  
					a.[YHM],  c.ZYMC,  a.[SFZH],  a.[ZZMM],  a.[SSNJ],  
					CASE a.[XZ]  
						WHEN 1 THEN '一年制'  
						WHEN 2 THEN '二年制'  
						WHEN 3 THEN '三年制'  
						WHEN 4 THEN '四年制'  
						WHEN 5 THEN '五年制'  
						WHEN 6 THEN '六年制'  
						ELSE '暂未提供'  
					END AS XZ,  
					a.[MZ],  a.[XSXH],  a.[BJMC],a.SSBJ,a.BJMC,
					b.XLMC,  d.JYZT,a.XSZP,a.FZJS,e.JSMC
				FROM   
					DATA_STUDENT a  
				LEFT JOIN   
					XLTTK b ON a.XLDM = b.ID  
				LEFT JOIN   
					ZYDMK c ON a.ZYDM = c.ID  
				LEFT JOIN   
					JYZTDMK d ON a.JYZT = d.ZTDM  
				LEFT JOIN 
					JSDMK e ON a.FZJS = e.ID  
				where a.SSBJ in (select BJID from JSBJDYK where JSID=(select ID from JSDMK where DLZH=@yhm))
				 --用于获取教师信息（姓名）
			else
				SELECT   
					a.[ID],  a.[XSXM],  a.[XSXB],  a.[BIRTH],  
					DATEDIFF(YEAR, [BIRTH], GETDATE()) AS NL,  
					a.[YHM],  c.ZYMC,  a.[SFZH],  a.[ZZMM],  a.[SSNJ],  
					CASE a.[XZ]  
						WHEN 1 THEN '一年制'  
						WHEN 2 THEN '二年制'  
						WHEN 3 THEN '三年制'  
						WHEN 4 THEN '四年制'  
						WHEN 5 THEN '五年制'  
						WHEN 6 THEN '六年制'  
						ELSE '暂未提供'  
					END AS XZ,  
					a.[MZ],  a.[XSXH],  a.[BJMC],a.SSBJ,a.BJMC,
					b.XLMC,  d.JYZT,a.XSZP,a.FZJS,e.JSMC
				FROM   
					DATA_STUDENT a  
				LEFT JOIN   
					XLTTK b ON a.XLDM = b.ID  
				LEFT JOIN   
					ZYDMK c ON a.ZYDM = c.ID  
				LEFT JOIN   
					JYZTDMK d ON a.JYZT = d.ZTDM  
				LEFT JOIN 
					JSDMK e ON a.FZJS = e.ID  
				where a.SSBJ in (select BJID from JSBJDYK where JSID=(select ID from JSDMK where DLZH=@yhm))
				and a.QYDM=@yhm
				 --用于获取教师信息（姓名）
		end
	IF @yhsfdm=1-- 管理员
		begin
			if @qydm=2 --获取全部
				 -- 查询所有学生信息  
				SELECT   
					a.[ID],  a.[XSXM],  a.[XSXB],  a.[BIRTH],  
					DATEDIFF(YEAR, [BIRTH], GETDATE()) AS NL,  
					a.[YHM],  c.ZYMC,  a.[SFZH],  a.[ZZMM],  a.[SSNJ],  
					CASE a.[XZ]  
						WHEN 1 THEN '一年制'  
						WHEN 2 THEN '二年制'  
						WHEN 3 THEN '三年制'  
						WHEN 4 THEN '四年制'  
						WHEN 5 THEN '五年制'  
						WHEN 6 THEN '六年制'  
						ELSE '暂未提供'  
					END AS XZ,  
					a.[MZ],  a.[XSXH],  a.[BJMC],a.SSBJ,a.BJMC,
					b.XLMC,  d.JYZT,a.XSZP,a.FZJS,e.JSMC
				FROM   
					DATA_STUDENT a  
				LEFT JOIN   
					XLTTK b ON a.XLDM = b.ID  
				LEFT JOIN   
					ZYDMK c ON a.ZYDM = c.ID  
				LEFT JOIN   
					JYZTDMK d ON a.JYZT = d.ZTDM  
				LEFT JOIN 
					JSDMK e ON a.FZJS = e.ID  
				where a.SSBJ in (select BJID from JSBJDYK where JSID=(select ID from JSDMK where DLZH=@yhm))
				 --用于获取教师信息（姓名）
			else
				SELECT   
					a.[ID],  a.[XSXM],  a.[XSXB],  a.[BIRTH],  
					DATEDIFF(YEAR, [BIRTH], GETDATE()) AS NL,  
					a.[YHM],  c.ZYMC,  a.[SFZH],  a.[ZZMM],  a.[SSNJ],  
					CASE a.[XZ]  
						WHEN 1 THEN '一年制'  
						WHEN 2 THEN '二年制'  
						WHEN 3 THEN '三年制'  
						WHEN 4 THEN '四年制'  
						WHEN 5 THEN '五年制'  
						WHEN 6 THEN '六年制'  
						ELSE '暂未提供'  
					END AS XZ,  
					a.[MZ],  a.[XSXH],  a.[BJMC],a.SSBJ,a.BJMC,
					b.XLMC,  d.JYZT,a.XSZP,a.FZJS,e.JSMC
				FROM   
					DATA_STUDENT a  
				LEFT JOIN   
					XLTTK b ON a.XLDM = b.ID  
				LEFT JOIN   
					ZYDMK c ON a.ZYDM = c.ID  
				LEFT JOIN   
					JYZTDMK d ON a.JYZT = d.ZTDM  
				LEFT JOIN 
					JSDMK e ON a.FZJS = e.ID  
				where a.QYDM=@yhm
		end
		
END;
GO


