-- ----------------------------
-- Triggers structure for table DATA_ZPHJLK
-- ----------------------------
CREATE TRIGGER [dbo].[trg_AfterUpdate_DATA_ZPHJLK]
ON [dbo].[DATA_ZPHJLK]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;
	-- deleted 旧表数据
	-- inserted 新表数据
	--exec LuodengTable 'XXDMK'
	--exec LuodengTable 'DATA_ZPHJLK'
	declare @Old_SHDM int 
	declare @New_SHDM int
	declare @SHR nvarchar(50)
	declare @SHRSFDM int
	declare @SHSJ datetime
	declare @FBZ datetime
	declare  @FBZSFDM int 
	declare @FBZXM nvarchar(50)
	declare @SHRXM nvarchar(50)


	select @Old_SHDM=SHDM from deleted
	select @New_SHDM=SHDM,@SHR=SHRYHM,@SHRSFDM=SHRSFDM ,@FBZ=FBZ,@FBZSFDM=FBZSFDM from inserted

	-- 获取发布者信息
	if @FBZSFDM=1
		select @FBZXM=MC from GLYDMK where DLZH=@FBZ
	if @FBZSFDM=2
		select @FBZXM=JSMC from JSDMK where DLZH=@FBZ
	if @FBZSFDM=3 
		select @FBZXM=YHXM from DWYHK where YHM=@FBZ

	-- 获取审核人信息
	if @SHRSFDM=1
		select @SHRXM=MC from GLYDMK where DLZH=@SHR
	if @SHRSFDM=2
		select @SHRXM=JSMC from JSDMK where DLZH=@SHR
 --select * from    XXDMK
 --动作类型: 1 单位用户确认投递  2 单位用户回应投递  3 单位用户安排面试  4 单位用户录入结果 5学生预览岗位 6 学生投递 7 新增系统请求
 --8单位用户更新面试信息 9 单位用户取消面试 10学生确认面试11 单位申请招聘会  12、招聘会审核
	if @Old_SHDM!=@New_SHDM
		begin
	declare @ZPHBT nvarchar(200)
	select @ZPHBT = ZPHBT from inserted

	if @New_SHDM=1 and @Old_SHDM=0
		begin 
		--select @SHSJ=SHSJ from inserted
		insert into XXDMK(
			CFZ,CFZXW,JSZ,DZLX,CFZSFDM,JSZSFDM,DZNR
		) values (
			@SHR, '审核了招聘会请求', @FBZ, 12, @SHRSFDM, @FBZSFDM,
			@SHRXM + '已审核了招聘会:' + @ZPHBT --+ ',' + CONVERT(varchar(20), @SHSJ, 120)
		)
		end
	if @New_SHDM=0 and @Old_SHDM=1
		insert into XXDMK(
			CFZ,CFZXW,JSZ,DZLX,CFZSFDM,JSZSFDM,DZNR
		) values (
			@SHR, '取消了招聘会的审核', @FBZ, 13, @SHRSFDM, @FBZSFDM,
			@SHRXM + '取消了招聘会:' + @ZPHBT + '的审核'
		)
end

	else
		
		insert into SEMS_LOG(NR) values('DATA_ZPHJLK->UPDATE')
   
END;
GO

DISABLE TRIGGER [dbo].[trg_AfterUpdate_DATA_ZPHJLK] ON [dbo].[DATA_ZPHJLK]
GO


