CREATE TRIGGER [dbo].[trg_AfterInsert_TDJLK]
ON [dbo].[TDJLK]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN   
    DECLARE @STUID INT;  
    DECLARE @GWDM INT;  
	DECLARE @GWMC NVARCHAR(100)
	/*
		此触发器为INSERT 即学生投递简历
		1向XXDMK插入新消息
		2 更新DATA_GWDMK的投递次数+1

	   从 inserted 表获取新插入行的值  :
		STUID 学生ID
		GWDM 岗位代码
	*/
    SELECT   
        @STUID = STUID,  
        @GWDM = GWDM,
		@GWMC=b.GWMC
     FROM inserted a
	 left join DATA_GWDMK b on a.GWDM=b.ID ;  -- 'inserted' 表只有新插入的行  
	 /*
		ID	   消息代码
		CFZ	    触发者
		CFZXW	触发者行为
		CFSJ	消息产生时间
		JSZ	    接收者
		QBBZ	全部标志：即全部用户都可收到
		DZLX	动作类型: 1 单位用户确认投递  2 单位用户回应投递  3 单位用户安排面试  4 单位用户录入结果 5学生预览岗位 6 学生投递 7 新增系统请求 
		CFZSFDM	触发者身份代码   学生为4 来自YHSFDMK
		JSZSFDM	接收者身份代码   
		DZNR    动作内容
	 */
	 DECLARE @GWFBZ NVARCHAR(50); -- 岗位发布者用户名
     DECLARE @FBZSFDM INT;        -- 发布者身份代码 
	 select @GWFBZ=FBZ,@FBZSFDM=FBZYHSFDM from DATA_GWDMK where ID=@GWDM

	INSERT INTO XXDMK(CFZ,CFZXW,JSZ,DZLX,DZNR,CFZSFDM,JSZSFDM) 
	 values((select YHM from DATA_STUDENT where ID=@STUID),
	          '学生投递了岗位',@GWFBZ,6,'学生投递岗位:“'+@GWMC+'”',4,@FBZSFDM)
			 
			  -- exec LuodengTable 'DATA_GWDMK'
	UPDATE DATA_GWDMK SET  TDCS= TDCS +  1 WHERE ID=@GWDM;
END;
GO

CREATE TRIGGER [dbo].[trg_AfterUpdate_TDJLK]
ON [dbo].[TDJLK]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN  
    /*  
	单位用户回应学生的投递时、确认学生的投递时候，会执行此触发器：将回应消息插入到XXDMK里  
	备注：
	在 SQL Server 的 UPDATE 触发器中，INSERTED 和 DELETED 伪表的角色有所不同：
		INSERTED 伪表：
		INSERTED 表包含了所有 更新后的值。也就是说，当一行被更新时，INSERTED 表里的数据是完成更新后该行的最新状态。
		DELETED 伪表：
		DELETED 表则包含了对应更新前的值。它表现得像是被删除行的快照，显示了在更新操作之前，行的状态。
		示例
	*/  

    DECLARE @ISHY INT;  -- 是否是回应  
    DECLARE @QRDM INT;  -- 若QRDM变成1，就是单位确认  
    DECLARE @QYDM INT;  -- 若QYDM变成0 则为学生撤销，对与QYDM变成1的情况，是学生继续投递，学生撤销投递也是不去关注，我们不再去关注，也不发给单位  
	DECLARE @ISMS INT; -- 更新ISMS字段也会触发这个触发器，所以做判断，由0 变1时就判断为安排了面试但是，不去新增XXDMK
    SELECT @ISHY = HYDM, @QRDM = QRDM, @QYDM = QYDM FROM INSERTED;  
	--1 单位用户确认投递  2 单位用户回应投递  3 单位用户安排面试  4 单位用户录入结果 5学生预览岗位 6 学生投递 7 新增系统请求
    -- 注意：QRDM、HYDM不可能由1变0，当QYDM由1变成0时为学生撤销流程  

	SELECT @ISMS=ISMS  from  INSERTED;
	IF @ISMS=0
		BEGIN
			IF @ISHY = 1  -- 此为单位回应  
			BEGIN  
				-- 将新值插入到XXDMK表  
				INSERT INTO XXDMK (  
					CFZ,        -- 触发者单位用户名  
					CFZXW,      -- 触发者行为：单位回应了投递  
					JSZ,        -- 接收者：学生用户名  
					DZLX,       -- 动作类型: 2：单位用户回应投递  
					CFZSFDM,    -- 单位用户编码  
					JSZSFDM,    -- 学生编码  
					DZNR        -- 单位回应内容  
				)  
				SELECT  
					c.FBZ AS CFZ,                 -- 触发者单位用户名  
					'单位回应了投递' AS CFZXW,  -- 触发者行为  
					b.YHM AS JSZ,                 -- 获取接收者：学生用户名  
					2 AS DZLX,                     -- 动作类型  
					c.FBZYHSFDM AS CFZSFDM,       -- 单位用户的编码  
					4 AS JSZSFDM,                 -- 学生的编码  
					a.HYNR AS DZNR                 -- 单位回应内容  
				FROM   
					INSERTED a  
				LEFT JOIN DATA_STUDENT b ON a.STUID = b.ID  
				LEFT JOIN DATA_GWDMK c ON a.GWDM = c.ID;  
			END  
			ELSE IF @ISHY = 0 AND @QRDM = 1  -- 此为单位确认  
			BEGIN  
				-- 将新值插入到XXDMK表  
				INSERT INTO XXDMK (  
					CFZ,        -- 触发者单位用户名  
					CFZXW,      -- 触发者行为：单位确认了投递  
					JSZ,        -- 接收者：学生用户名  
					DZLX,       -- 动作类型: 1：单位用户确认投递  
					CFZSFDM,    -- 单位用户编码  
					JSZSFDM,    -- 学生编码  
					DZNR        -- 单位回应内容  
				)  
				SELECT  
					c.FBZ AS CFZ,                  -- 触发者单位用户名  
					'单位确认了投递' AS CFZXW,   -- 触发者行为  
					b.YHM AS JSZ,                  -- 获取接收者：学生用户名  
					1 AS DZLX,                      -- 动作类型  
					c.FBZYHSFDM AS CFZSFDM,        -- 单位用户的编码  
					4 AS JSZSFDM,                  -- 学生的编码  
					'单位收到了您的 "' + c.GWMC + '" 职位投递' AS DZNR  -- 单位回应内容  
				FROM   
					INSERTED a  
				LEFT JOIN DATA_STUDENT b ON a.STUID = b.ID  
				LEFT JOIN DATA_GWDMK c ON a.GWDM = c.ID;  
			END  
		END
END;

/*
  ELSE IF @QYDM = 0  -- 此为学生撤销投递---
    BEGIN  
        -- 将新值插入到XXDMK表  
        INSERT INTO XXDMK (  
            CFZ,        -- 触发者单位用户名  
            CFZXW,      -- 触发者行为：单位回应了投递  
            JSZ,        -- 接收者：学生用户名  
            DZLX,       -- 动作类型: 2：单位用户回应投递  
            CFZSFDM,    -- 单位用户编码  
            JSZSFDM,    -- 学生编码  
            DZNR        -- 单位回应内容  
        )  
        SELECT  
            c.FBZ AS CFZ,                  -- 触发者单位用户名  
            '单位回应了投递' AS CFZXW,   -- 触发者行为  
            b.YHM AS JSZ,                  -- 获取接收者：学生用户名  
            2 AS DZLX,                      -- 动作类型  
            c.FBZYHSFDM AS CFZSFDM,        -- 单位用户的编码  
            4 AS JSZSFDM,                  -- 学生的编码  
            a.HYNR AS DZNR                  -- 单位回应内容  
        FROM   
            INSERTED a  
        LEFT JOIN DATA_STUDENT b ON a.STUID = b.ID  
        LEFT JOIN DATA_GWDMK c ON a.GWDM = c.ID;  
    END   
*/
GO


-- ----------------------------
-- Triggers structure for table TJDXK
-- ----------------------------
CREATE TRIGGER [dbo].[trg_after_insert_TJDXK]
ON [dbo].[TJDXK]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	-- 通知给涉及的学生

	--exec LuodengTable 'TJGWK'
	--exec LuodengTable 'TJDXK'

	--1、先看推荐到学生的--获取学生代码
   -- select b.DXDM from TJDXK b where INSERTED b.TJDM in (select * from TJGWK a where a.YJLB=1 and a.QYDM=1 )
--如果希望包含重复值，则用 UNION ALL；如果想去重，用 UNION。 #表自动清除
   CREATE TABLE #STUIDLIST (
    STUID INT
		);

	-- 临时表插入学生ID（已去重）
-- 插入学生ID到临时表
INSERT INTO #STUIDLIST (STUID)
SELECT DXDM FROM INSERTED WHERE DXLX = 1
UNION
SELECT ID FROM DATA_STUDENT WHERE SSBJ IN (
    SELECT DXDM FROM INSERTED WHERE DXLX = 2
);

-- 触发者信息
DECLARE @CFZ NVARCHAR(50), @CFZSFDM INT,@TJMS NVARCHAR(500),@TJSJ datetime;

SELECT TOP 1 
    @CFZ = tj.TJR, 
    @CFZSFDM = tj.TJRSFDM
FROM TJGWK tj
JOIN INSERTED i ON tj.ID = i.TJDM;

-- 定义遍历变量
DECLARE @STUID INT;
DECLARE @YHM NVARCHAR(50);--学生用户名
DECLARE @GWMC NVARCHAR(100);
DECLARE @DZNR NVARCHAR(500);
DECLARE @CFZXM NVARCHAR(50);--触发者姓名

-- 游标式处理（WHILE 模拟）
DECLARE @rowcount INT = 0;

-- 添加一个临时表带自增主键做“游标索引”
CREATE TABLE #IndexList (
    RowID INT IDENTITY(1,1),
    STUID INT
);

INSERT INTO #IndexList (STUID)
SELECT STUID FROM #STUIDLIST;

SELECT @rowcount = COUNT(*) FROM #IndexList;

DECLARE @i INT = 1;

-- 获取岗位信息、推荐信息
    SELECT 
        @GWMC = f.GWMC,
		@TJMS=g.TJMS,
		@TJSJ=g.TJSJ
    FROM INSERTED i
     left JOIN TJGWK g ON g.ID = i.TJDM
	 left join DATA_GWDMK f ON g.GWDM=f.ID

-- 获取推荐者信息
if @CFZSFDM=2 
	select @CFZXM=JSMC from JSDMK where DLZH=@CFZ
if @CFZSFDM=1 
	select @CFZXM=MC from GLYDMK where DLZH=@CFZ

WHILE @i <= @rowcount
BEGIN
    -- 获取当前学生 ID
    SELECT @STUID = STUID FROM #IndexList WHERE RowID = @i;

    -- 获取学生用户名
    SELECT @YHM = YHM FROM DATA_STUDENT WHERE ID = @STUID;

    

    -- 组装动作内容
    SET @DZNR = @CFZXM+' 为你推荐岗位:' + @GWMC + ',推荐理由:' + @TJMS+',推荐时间：' + CONVERT(VARCHAR, @TJSJ, 120) ;

    -- 插入消息
    INSERT INTO XXDMK (
        CFZ,
        CFZXW,
        JSZ,
        DZLX,
        CFZSFDM,
        JSZSFDM,
        DZNR
    )
    VALUES (
        @CFZ,  --触发者
        '为学生推荐岗位',--触发者行为
        @YHM,--接收者用户名
        14, --动作类型
        @CFZSFDM,--触发者SFDM
        4,--接收者身份代码
        @DZNR --动作内容
    );

    SET @i = @i + 1;
END

-- 清理
DROP TABLE #IndexList;


								 
END;
GO


