CREATE TRIGGER [dbo].[trg_after_delete_TJGWK]
ON [dbo].[TJGWK]
WITH EXECUTE AS CALLER
FOR DELETE
AS
BEGIN
    SET NOCOUNT ON;

	-- 删除推荐岗位信息，就会联动删除对象
	delete from TJDXK where TJDM =(select ID from deleted)
	
END;
